mapper.select:
select
  id, study_id, patient_id, exam_no, test_no, create_time, update_time, result_time, abnormal_indicator_high, abnormal_indicator_low, serum_lactate_dehydrogenase, aspartate_aminotransferase, serum_creatine_kinase_mb_assay, serum_creatine_kinase_assay, hbdh
from td_myocardia_enzyme


        and id = #{id}


        and study_id = #{studyId}


        and patient_id = #{patientId}


        and exam_no = #{examNo}


        and test_no = #{testNo}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and result_time = #{resultTime}


        and abnormal_indicator_high = #{abnormalIndicatorHigh}


        and abnormal_indicator_low = #{abnormalIndicatorLow}


        and serum_lactate_dehydrogenase = #{serumLactateDehydrogenase}


        and aspartate_aminotransferase = #{aspartateAminotransferase}


        and serum_creatine_kinase_mb_assay = #{serumCreatineKinaseMbAssay}


        and serum_creatine_kinase_assay = #{serumCreatineKinaseAssay}


        and hbdh = #{hbdh}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from td_myocardia_enzyme


        and id = #{id}


        and study_id = #{studyId}


        and patient_id = #{patientId}


        and exam_no = #{examNo}


        and test_no = #{testNo}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and result_time = #{resultTime}


        and abnormal_indicator_high = #{abnormalIndicatorHigh}


        and abnormal_indicator_low = #{abnormalIndicatorLow}


        and serum_lactate_dehydrogenase = #{serumLactateDehydrogenase}


        and aspartate_aminotransferase = #{aspartateAminotransferase}


        and serum_creatine_kinase_mb_assay = #{serumCreatineKinaseMbAssay}


        and serum_creatine_kinase_assay = #{serumCreatineKinaseAssay}


        and hbdh = #{hbdh}
